SELECT pg_advisory_xact_lock(87261008);
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password text NOT NULL, totp text, totp_pending text, totp_counter bigint NOT NULL DEFAULT 0, mfa text, phone text, verified integer NOT NULL DEFAULT 0, created bigint NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires bigint NOT NULL, verified integer NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS challenges (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, hash text NOT NULL, expires bigint NOT NULL);
CREATE INDEX IF NOT EXISTS challenges_owner_kind ON challenges(user_id,kind);
CREATE TABLE IF NOT EXISTS files (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, type text NOT NULL, size bigint NOT NULL, created bigint NOT NULL);
CREATE INDEX IF NOT EXISTS files_owner ON files(user_id);
CREATE TABLE IF NOT EXISTS records (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, payload text NOT NULL, updated bigint NOT NULL, account_id text REFERENCES records(id), target_id text REFERENCES records(id), source_id text REFERENCES records(id), attachment_id text REFERENCES files(id));
CREATE INDEX IF NOT EXISTS records_owner_kind ON records(user_id,kind);
CREATE INDEX IF NOT EXISTS records_source ON records(user_id,source_id);
CREATE TABLE IF NOT EXISTS limits (key text PRIMARY KEY, count bigint NOT NULL, expires bigint NOT NULL);
CREATE TABLE IF NOT EXISTS uploads (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, type text NOT NULL, expected_size bigint NOT NULL, created bigint NOT NULL, expires bigint NOT NULL);
CREATE INDEX IF NOT EXISTS uploads_owner ON uploads(user_id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar bytea;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_updated bigint NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS disabled integer NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS timezone text NOT NULL DEFAULT 'America/Sao_Paulo';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS id text DEFAULT gen_random_uuid()::text;
UPDATE sessions SET id=gen_random_uuid()::text WHERE id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS sessions_public_id ON sessions(id);
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS created bigint NOT NULL DEFAULT 0;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS last_seen bigint NOT NULL DEFAULT 0;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS device text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS browser text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS os text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS label text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS ip text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS city text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS region text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS country text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS security_events (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, created bigint NOT NULL, device text NOT NULL DEFAULT '', browser text NOT NULL DEFAULT '', os text NOT NULL DEFAULT '', ip text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', region text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', detail text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS security_events_owner ON security_events(user_id,created DESC);

CREATE TABLE IF NOT EXISTS user_preferences (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,payload text NOT NULL DEFAULT '{}',updated bigint NOT NULL);
CREATE TABLE IF NOT EXISTS reconciliation_keys (key text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,account_id text NOT NULL REFERENCES records(id),record_id text NOT NULL REFERENCES records(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fx_quotes (currency text NOT NULL,quote_date text NOT NULL,rate double precision NOT NULL,updated bigint NOT NULL,PRIMARY KEY(currency,quote_date));
CREATE TABLE IF NOT EXISTS financial_backups (user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,day text NOT NULL,payload text NOT NULL,created bigint NOT NULL,PRIMARY KEY(user_id,day));
ALTER TABLE fx_quotes ADD COLUMN IF NOT EXISTS source_date text;
CREATE TABLE IF NOT EXISTS passkeys (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,public_key bytea NOT NULL,counter bigint NOT NULL DEFAULT 0,transports text NOT NULL DEFAULT '[]',label text NOT NULL,created bigint NOT NULL,rp_id text NOT NULL);
CREATE TABLE IF NOT EXISTS webauthn_challenges (id text PRIMARY KEY,user_id text REFERENCES users(id) ON DELETE CASCADE,kind text NOT NULL,challenge text NOT NULL,origin text NOT NULL,expires bigint NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,payload text NOT NULL,created bigint NOT NULL,last_day text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS push_owner ON push_subscriptions(user_id);
